UPDATE t_coupon_template_outbox
SET status = 'RETRY', retry_at = #{now}, worker_id = NULL, lease_until = NULL, update_time = NOW()
WHERE status = 'PROCESSING' AND lease_until < #{now}

UPDATE t_coupon_template_outbox
SET status = 'DONE', worker_id = NULL, lease_until = NULL, update_time = NOW()
WHERE id = #{id} AND shop_number = #{shopNumber} AND status = 'PROCESSING' AND worker_id = #{workerId}
